		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.xoq.xpc!=undefined){
			
			if(gameController.ngo!=parseInt(tmpMess[1])){
				
			gameController.ngo=parseInt(tmpMess[1]);	
			gameController.xoq.xpc.bye("creditd", "#asj", [gameController.prf(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
